drochloride","manufacturer":"Renata PLC.","strength":"2 mg","form":"tablet","prescription_only":true},{"brand_name":"Alphapress XR","generic_name":"Prazosin Hydrochloride","manufacturer":"Renata PLC.","strength":"2.5 mg","form":"tablet","prescription_only":true},{"brand_name":"Alurol","generic_name":"Allopurinol","manufacturer":"Incepta Pharmaceuticals Ltd.","strength":"100 mg","form":"tablet","prescription_only":true},{"brand_name":"Alzacare","generic_name":"Memantine + Donepezil","manufacturer":"Renata PLC.","strength":"28 mg+10 mg","form":"capsule","prescription_only":true},{"brand_name":"Ambolyt","generic_name":"Ambroxol Hydrochloride","manufacturer":"Incepta Pharmaceuticals Ltd.","strength":"15 mg/5 ml","form":"syrup","prescription_only":true},{"brand_name":"Ambolyt SR","generic_name":"Ambroxol Hydrochloride","manufacturer":"Incepta Pharmaceuticals Ltd.","strength":"75 mg","form":"capsule","prescription_only":true}]$meds$::jsonb)
    as x(brand_name text,strength text,form text))),
p as (select id,substring(name from 6) as label,
  case area when 'dhanmondi' then 'dhanmondi' when 'mirpur-10' then 'mirpur'
   when 'mohakhali' then 'mohakhali' else area end as key,
  row_number() over(order by id) as rn from public.pharmacies
  where licence_number like 'DEMO-%')
insert into public.pharmacy_stock(pharmacy_id,medicine_id,quantity,held_quantity,selling_price,expiry_date)
select p.id,m.id,case when m.brand_name='Ace' and p.key='dhanmondi' then 20
 else 1+mod((m.rn*7+p.rn*11)::integer,80) end,0,
 (10+mod((m.rn*7+p.rn*3)::integer,75))::numeric,
 case when m.brand_name='Ace' and p.key='dhanmondi' then '2026-10-31'::date
 else '2027-12-31'::date end
from m cross join p
where (m.brand_name='Seclo' and p.key in ('dhanmondi','mirpur','mohakhali'))
 or (m.brand_name='Napa' and p.key in ('dhanmondi','mohakhali','banani'))
 or (m.brand_name not in ('Seclo','Napa') and mod((m.rn+p.rn)::integer,3)<>0)
on conflict (pharmacy_id,medicine_id) do nothing;
